/* 학습 해설
 * Stack depot early init 한 번과 장애 비활성화
 * Linux의 stack 기록 중복 제거·hash 충돌·압축 handle·참조 수·RCU 재사용·pool 할당·진단 API의 원리와 사용 계약을 배웁니다.
 * early_init은 한 번 호출되도록 passed 상태를 검사하고 처음 진입에서true로 만듭니다. disabled면 안내 후0, 요청하지 않았으면 KASAN bucket 크기 정책을 정한 뒤0을 반환합니다. early hash 할당 실패는 disabled=true와 -ENOMEM으로 이어집니다.
 * 요청 유무·중복 호출·할당 실패의 세 흐름을 표로 적으세요.0반환이 항상 table 생성이라는 뜻은 아니며 skip된 초기화와 이미 완료 상태를 구별합니다.
 */
int __init stack_depot_early_init(void)
{
	unsigned long entries = 0;

	/* This function must be called only once, from mm_init(). */
	if (WARN_ON(__stack_depot_early_init_passed))
		return 0;
	__stack_depot_early_init_passed = true;

	/*
	 * Print disabled message even if early init has not been requested:
	 * stack_depot_init() will not print one.
	 */
	if (stack_depot_disabled) {
		pr_info("disabled\n");
		return 0;
	}

	/*
	 * If KASAN is enabled, use the maximum order: KASAN is frequently used
	 * in fuzzing scenarios, which leads to a large number of different
