/* 학습 해설
 * Stack depot fetch의 pool 해석과 count0 거부
 * Linux의 stack 기록 중복 제거·hash 충돌·압축 handle·참조 수·RCU 재사용·pool 할당·진단 API의 원리와 사용 계약을 배웁니다.
 * fetch는 handle의 pool_index_plus_1에서1을 빼고 offset을16byte 단위로 복원합니다. pool 수 범위를 확인하고 pool pointer·refcount 비영을 검사합니다. 모든 임의 offset의 정렬·실제 record 시작을 완전히 검증하는 입력 validator로 설명하면 실제 조건보다 강해집니다.
 * put으로 count0인 record의 fetch가NULL인지 확인하세요. fixture는 임의 잘못된 offset을 역참조하지 않으며 유효한 handle 또는0·해제된 record만 사용했습니다.
 */
static struct stack_record *depot_fetch_stack(depot_stack_handle_t handle)
{
	const int pools_num_cached = READ_ONCE(pools_num);
	union handle_parts parts = { .handle = handle };
	void *pool;
	u32 pool_index = parts.pool_index_plus_1 - 1;
	size_t offset = parts.offset << DEPOT_STACK_ALIGN;
	struct stack_record *stack;

	lockdep_assert_not_held(&pool_lock);

	if (pool_index >= pools_num_cached) {
		WARN(1, "pool index %d out of bounds (%d) for stack id %08x\n",
		     pool_index, pools_num_cached, handle);
		return NULL;
	}

	pool = stack_pools[pool_index];
	if (WARN_ON(!pool))
		return NULL;

	stack = pool + offset;
	if (WARN_ON(!refcount_read(&stack->count)))
		return NULL;

	return stack;

