 * Stack depot put의 hash 제거·union과 cookie
 * Linux의 stack 기록 중복 제거·hash 충돌·압축 handle·참조 수·RCU 재사용·pool 할당·진단 API의 원리와 사용 계약을 배웁니다.
 * refcount0이 되면 hash list에서 RCU 방식으로 제거하고 cookie를 얻어 free list tail에 넣습니다. record의 frame 배열과 freelist 관리 영역은 union으로 공간을 공유합니다.0ref일 때만 관리 영역으로 해석하고 다시 살아난 뒤에는 frame으로 해석하는 invariant가 중요합니다.
 * record의 hash_list와 union free_list를 따로 그리세요. 모델은 즉시 링크 제거와 유한cookie 상태로 순서를 확인하며 실제 지연된 RCU traversal·data_race 허용·LKMM은 실행하지 않았습니다.
 */
static void depot_free_stack(struct stack_record *stack)
{
	unsigned long flags;

	lockdep_assert_not_held(&pool_lock);

	raw_spin_lock_irqsave(&pool_lock, flags);
	printk_deferred_enter();

	/*
	 * Remove the entry from the hash list. Concurrent list traversal may
	 * still observe the entry, but since the refcount is zero, this entry
	 * will no longer be considered as valid.
	 */
	list_del_rcu(&stack->hash_list);

	/*
	 * Due to being used from constrained contexts such as the allocators,
	 * NMI, or even RCU itself, stack depot cannot rely on primitives that
	 * would sleep (such as synchronize_rcu()) or recursively call into
	 * stack depot again (such as call_rcu()).
	 *
	 * Instead, get an RCU cookie, so that we can ensure this entry isn't
	 * moved onto another list until the next grace period, and concurrent
	 * RCU list traversal remains safe.
	 */

