/* 학습 해설
 * Stack depot put 균형과 마지막 참조 해제
 * Linux의 stack 기록 중복 제거·hash 충돌·압축 handle·참조 수·RCU 재사용·pool 할당·진단 API의 원리와 사용 계약을 배웁니다.
 * put은 0·disabled를 제외하고 record를 조회한 뒤 refcount_dec_and_test가 0을 만들면 freelist 해제를 수행합니다. GET 두 번에는 put 두 번이 필요하며 첫 put은 record를 유지합니다. 잘못된 handle·unbalanced put 경고가 정상 수명 관리를 대신하는 것은 아닙니다.
 * count 2→1→0·hash 제거·cookie 등록을 순서표로 적으세요. 모델은 직렬 refcount이며 실제 atomic ordering·overflow saturation·동시 마지막 참조 경쟁은 실행하지 않았습니다.
 */
void stack_depot_put(depot_stack_handle_t handle)
{
	struct stack_record *stack;

	if (!handle || stack_depot_disabled)
		return;

	stack = depot_fetch_stack(handle);
	/*
	 * Should always be able to find the stack record, otherwise this is an
	 * unbalanced put attempt (or corrupt handle).
